func dedupe(items []int) []int {
	seen := make(map[int]struct{}, len(items))
	result := items[:0]
	for _, item := range items {
		if _, ok := seen[item]; ok {
			continue
		}
		seen[item] = struct{}{}
		result = append(result, item)
	}
	return result
}

