type NoteRepository struct {
	mu    sync.RWMutex
	notes map[domain.NoteID]*domain.Note
}

func NewNoteRepository() *NoteRepository {
	return &NoteRepository{notes: make(map[domain.NoteID]*domain.Note)}
}

func (r *NoteRepository) Save(_ context.Context, note *domain.Note) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	stored := *note
	r.notes[note.ID] = &stored
	return nil
}

func (r *NoteRepository) FindByID(_ context.Context, id domain.NoteID) (*domain.Note, error) {
	r.mu.RLock()
	defer r.mu.RUnlock()

	note, ok := r.notes[id]
	if !ok {
		return nil, ports.ErrNoteNotFound
	}

	found := *note
	return &found, nil
}

func (r *NoteRepository) FindAll(_ context.Context) ([]*domain.Note, error) {
	r.mu.RLock()
	defer r.mu.RUnlock()

	notes := make([]*domain.Note, 0, len(r.notes))
	for _, note := range r.notes {
		copyNote := *note
		notes = append(notes, &copyNote)
	}
	return notes, nil
}

func (r *NoteRepository) Delete(_ context.Context, id domain.NoteID) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	if _, ok := r.notes[id]; !ok {
		return ports.ErrNoteNotFound
	}
	delete(r.notes, id)
	return nil
}

