		if os.IsNotExist(err) {
			return make(map[string]noteRecord), nil
		}
		return nil, fmt.Errorf("jsonfile: read notes file: %w", err)
	}

	if len(data) == 0 {
		return make(map[string]noteRecord), nil
	}

	var records []noteRecord
	if err := json.Unmarshal(data, &records); err != nil {
		return nil, fmt.Errorf("jsonfile: decode notes file: %w", err)
	}

	byID := make(map[string]noteRecord, len(records))
	for _, rec := range records {
		byID[rec.ID] = rec
	}
	return byID, nil
}

func (r *NoteRepository) save(byID map[string]noteRecord) error {
	records := make([]noteRecord, 0, len(byID))
	for _, rec := range byID {
		records = append(records, rec)
	}

	data, err := json.MarshalIndent(records, "", "  ")
	if err != nil {
		return fmt.Errorf("jsonfile: encode notes file: %w", err)
	}

	if err := os.WriteFile(r.path, data, 0o644); err != nil {
		return fmt.Errorf("jsonfile: write notes file: %w", err)
	}
	return nil
}

func (r *NoteRepository) Save(_ context.Context, note *domain.Note) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	byID, err := r.load()
	if err != nil {
		return err
	}

	byID[note.ID.String()] = toRecord(note)

	return r.save(byID)
}

func (r *NoteRepository) FindByID(_ context.Context, id domain.NoteID) (*domain.Note, error) {
	r.mu.Lock()
	defer r.mu.Unlock()

	byID, err := r.load()
	if err != nil {
		return nil, err
	}

	rec, ok := byID[id.String()]
	if !ok {
		return nil, ports.ErrNoteNotFound
	}
	return rec.toDomain(), nil
}

func (r *NoteRepository) FindAll(_ context.Context) ([]*domain.Note, error) {
	r.mu.Lock()
	defer r.mu.Unlock()

	byID, err := r.load()
	if err != nil {
		return nil, err
	}

	notes := make([]*domain.Note, 0, len(byID))
	for _, rec := range byID {
		notes = append(notes, rec.toDomain())
	}
	return notes, nil
}

func (r *NoteRepository) Delete(_ context.Context, id domain.NoteID) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	byID, err := r.load()
	if err != nil {
		return err
	}

	if _, ok := byID[id.String()]; !ok {
		return ports.ErrNoteNotFound
	}
	delete(byID, id.String())

	return r.save(byID)
}

const timeLayout = "2006-01-02T15:04:05Z07:00"

type noteResponse struct {
	ID        string `json:"id"`
	Title     string `json:"title"`
	Content   string `json:"content"`
	CreatedAt string `json:"created_at"`
	UpdatedAt string `json:"updated_at"`
}

func newNoteResponse(n *domain.Note) noteResponse {
	return noteResponse{
		ID:        n.ID.String(),
		Title:     n.Title,
		Content:   n.Content,
		CreatedAt: n.CreatedAt.Format(timeLayout),
		UpdatedAt: n.UpdatedAt.Format(timeLayout),
	}
}

func newNoteResponses(notes []*domain.Note) []noteResponse {
	out := make([]noteResponse, 0, len(notes))
	for _, n := range notes {
		out = append(out, newNoteResponse(n))
	}
	return out
}

type createNoteRequest struct {
	Title   string `json:"title"`
	Content string `json:"content"`
}

type updateNoteRequest struct {
	Title   *string `json:"title"`
	Content *string `json:"content"`
}

type errorResponse struct {
	Error string `json:"error"`
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	if v == nil {
		return
	}
	if err := json.NewEncoder(w).Encode(v); err != nil {
		log.Printf("httpapi: failed to encode response: %v", err)
	}
}

func writeError(w http.ResponseWriter, err error) {
	switch {
	case errors.Is(err, domain.ErrEmptyTitle):
		writeJSON(w, http.StatusBadRequest, errorResponse{Error: err.Error()})
	case errors.Is(err, ports.ErrNoteNotFound):
		writeJSON(w, http.StatusNotFound, errorResponse{Error: err.Error()})
	default:
		log.Printf("httpapi: internal error: %v", err)
		writeJSON(w, http.StatusInternalServerError, errorResponse{Error: "internal server error"})
	}
}

func CreateHandler(uc *application.CreateNote) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		var req createNoteRequest
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			writeJSON(w, http.StatusBadRequest, errorResponse{Error: "invalid JSON body"})
			return
		}

		note, err := uc.Execute(r.Context(), application.CreateNoteInput{
			Title:   req.Title,
			Content: req.Content,
		})
		if err != nil {
			writeError(w, err)
			return
		}

		writeJSON(w, http.StatusCreated, newNoteResponse(note))
	}
}

func GetHandler(uc *application.GetNote) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id := r.PathValue("id")

		note, err := uc.Execute(r.Context(), domain.NoteID(id))
		if err != nil {
			writeError(w, err)
			return
		}

		writeJSON(w, http.StatusOK, newNoteResponse(note))
	}
}

func ListHandler(uc *application.ListNotes) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		notes, err := uc.Execute(r.Context())
		if err != nil {
			writeError(w, err)
			return
		}

		writeJSON(w, http.StatusOK, newNoteResponses(notes))
	}
}

func UpdateHandler(uc *application.UpdateNote) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id := r.PathValue("id")

		var req updateNoteRequest
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			writeJSON(w, http.StatusBadRequest, errorResponse{Error: "invalid JSON body"})
			return
		}

		note, err := uc.Execute(r.Context(), domain.NoteID(id), application.UpdateNoteInput{
			Title:   req.Title,
			Content: req.Content,
		})
		if err != nil {
			writeError(w, err)
			return
		}

		writeJSON(w, http.StatusOK, newNoteResponse(note))
	}
}

func DeleteHandler(uc *application.DeleteNote) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id := r.PathValue("id")

		if err := uc.Execute(r.Context(), domain.NoteID(id)); err != nil {
			writeError(w, err)
			return
		}

		w.WriteHeader(http.StatusNoContent)
	}
