func (IDGenerator) NewID() domain.NoteID {
	buf := make([]byte, 8)
	if _, err := rand.Read(buf); err != nil {
		return domain.NoteID(strconv.FormatInt(time.Now().UnixNano(), 16))
	}
	return domain.NoteID(hex.EncodeToString(buf))
