func (m model) Init() tea.Cmd {
	return tea.Batch(m.spinner.Tick, loadNotes(m.listNotes))
}

func (m model) handleKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	if m.mode == modeAdd {
		switch msg.String() {
		case "enter":
			if strings.TrimSpace(m.input.Value()) == "" {
				return m, nil
			}
			return m, addNote(m.addNote, m.input.Value())
		case "esc":
			m.mode = modeList
			m.input.Blur()
			m.input.SetValue("")
			return m, nil
		}
		var cmd tea.Cmd
		m.input, cmd = m.input.Update(msg)
		return m, cmd
	}

	switch msg.String() {
	case "q", "ctrl+c":
		return m, tea.Quit
	case "up", "k":
		if m.cursor > 0 {
			m.cursor--
		}
	case "down", "j":
		if m.cursor < len(m.notes)-1 {
			m.cursor++
		}
	case "a":
		m.mode = modeAdd
		m.err = nil
		cmd := m.input.Focus()
		return m, cmd
	case "d":
		if len(m.notes) > 0 {
			return m, deleteNote(m.deleteNote, m.notes[m.cursor].ID())
		}
	}
	return m, nil
}

func (m model) renderList() string {
	var b strings.Builder
	for i, note := range m.notes {
		cursor := "  "
		line := fmt.Sprintf("%s  %s", note.CreatedAt().Format("2006-01-02 15:04"), note.Title())
		if i == m.cursor {
			cursor = selectedStyle.Render("> ")
			line = selectedStyle.Render(line)
		}
		b.WriteString(cursor + line + "\n")
	}
	return strings.TrimRight(b.String(), "\n")
}

func (m model) View() string {
	var b strings.Builder
	b.WriteString(titleStyle.Render("notes") + "\n\n")
	b.WriteString(m.renderBody())

	if m.err != nil {
		b.WriteString("\n" + errorStyle.Render("error: "+m.err.Error()))
	}
	if m.mode == modeList {
		b.WriteString("\n" + hintStyle.Render("up/down move - a add - d delete - q quit"))
	}
	return panelStyle.Render(b.String())
}

func (m model) renderBody() string {
	switch {
	case m.loading:
		return m.spinner.View() + " " + hintStyle.Render("loading notes...")
	case m.mode == modeAdd:
		return m.input.View()
	case len(m.notes) == 0:
		return hintStyle.Render("no notes yet - press a to add one")
	default:
		return m.renderList()
	}
}

