func LinearSearch(nums []int, target int) int {
	for i, n := range nums {
		if n == target {
			return i
		}
	}
	return -1
}

func BinarySearch(nums []int, target int) int {
	lo, hi := 0, len(nums)-1
	for lo <= hi {
		mid := lo + (hi-lo)/2
		switch {
		case nums[mid] == target:
			return mid
		case nums[mid] < target:
			lo = mid + 1
		default:
			hi = mid - 1
		}
	}
	return -1
}

func BubbleSort(nums []int) {
	for i := 0; i < len(nums)-1; i++ {
		for j := 0; j < len(nums)-1-i; j++ {
			if nums[j] > nums[j+1] {
				nums[j], nums[j+1] = nums[j+1], nums[j]
			}
		}
	}
}

func SelectionSort(nums []int) {
	for i := 0; i < len(nums)-1; i++ {
		min := i
		for j := i + 1; j < len(nums); j++ {
			if nums[j] < nums[min] {
				min = j
			}
		}
		nums[i], nums[min] = nums[min], nums[i]
	}
}

func InsertionSort(nums []int) {
	for i := 1; i < len(nums); i++ {
		key := nums[i]
		j := i - 1
		for j >= 0 && nums[j] > key {
			nums[j+1] = nums[j]
			j--
		}
		nums[j+1] = key
	}
}

func MergeSort(nums []int) []int {
	if len(nums) <= 1 {
		return nums
	}
	mid := len(nums) / 2
	left := MergeSort(nums[:mid])
	right := MergeSort(nums[mid:])
	return merge(left, right)
}

func merge(left, right []int) []int {
	result := make([]int, 0, len(left)+len(right))
	i, j := 0, 0
	for i < len(left) && j < len(right) {
		if left[i] <= right[j] {
			result = append(result, left[i])
			i++
		} else {
			result = append(result, right[j])
			j++
		}
	}
	result = append(result, left[i:]...)
	result = append(result, right[j:]...)
	return result
}

func QuickSort(nums []int, low, high int) {
	if low < high {
		p := partition(nums, low, high)
		QuickSort(nums, low, p-1)
		QuickSort(nums, p+1, high)
	}
}

func partition(nums []int, low, high int) int {
	pivot := nums[high]
	i := low - 1
	for j := low; j < high; j++ {
		if nums[j] < pivot {
			i++
			nums[i], nums[j] = nums[j], nums[i]
		}
	}
	nums[i+1], nums[high] = nums[high], nums[i+1]
	return i + 1
}

func HeapSort(nums []int) {
	n := len(nums)
	for i := n/2 - 1; i >= 0; i-- {
		siftDown(nums, i, n)
	}
	for i := n - 1; i > 0; i-- {
		nums[0], nums[i] = nums[i], nums[0]
		siftDown(nums, 0, i)
	}
}

func siftDown(nums []int, root, size int) {
	for {
		largest := root
		left, right := 2*root+1, 2*root+2
		if left < size && nums[left] > nums[largest] {
			largest = left
		}
		if right < size && nums[right] > nums[largest] {
			largest = right
		}
		if largest == root {
			return
		}
		nums[root], nums[largest] = nums[largest], nums[root]
		root = largest
	}
}

type Graph struct {
	edges map[string][]string
}

func NewGraph() *Graph {
	return &Graph{edges: make(map[string][]string)}
}

func (g *Graph) AddEdge(from, to string) {
	g.edges[from] = append(g.edges[from], to)
	g.edges[to] = append(g.edges[to], from)
}

func BFS(g *Graph, start string) []string {
	visited := map[string]bool{start: true}
	queue := []string{start}
	var order []string
	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]
		order = append(order, node)
		for _, neighbor := range g.edges[node] {
			if !visited[neighbor] {
				visited[neighbor] = true
				queue = append(queue, neighbor)
			}
		}
	}
	return order
}

func DFS(g *Graph, start string) []string {
	visited := make(map[string]bool)
	var order []string
	visitDFS(g, start, visited, &order)
	return order
}

func visitDFS(g *Graph, node string, visited map[string]bool, order *[]string) {
	if visited[node] {
		return
	}
	visited[node] = true
	*order = append(*order, node)
	for _, neighbor := range g.edges[node] {
		visitDFS(g, neighbor, visited, order)
	}
}

type Edge struct {
	To     string
	Weight int
}

type WeightedGraph struct {
	edges map[string][]Edge
}

func (g *WeightedGraph) AddEdge(from, to string, weight int) {
	g.edges[from] = append(g.edges[from], Edge{To: to, Weight: weight})
	g.edges[to] = append(g.edges[to], Edge{To: from, Weight: weight})
}

func Dijkstra(g *WeightedGraph, start string, nodes []string) map[string]int {
	dist := make(map[string]int)
	visited := make(map[string]bool)
	for _, n := range nodes {
		dist[n] = math.MaxInt
	}
	dist[start] = 0

	for len(visited) < len(nodes) {
		current := closestUnvisited(dist, visited)
		if current == "" {
			break
		}
		visited[current] = true
		for _, edge := range g.edges[current] {
			newDist := dist[current] + edge.Weight
			if newDist < dist[edge.To] {
				dist[edge.To] = newDist
			}
		}
	}
	return dist
}

func closestUnvisited(dist map[string]int, visited map[string]bool) string {
	best := ""
	bestDist := math.MaxInt
	for node, d := range dist {
		if !visited[node] && d < bestDist {
			best = node
			bestDist = d
		}
	}
	return best
}

