type TaskStore interface {
	Create(ctx context.Context, input TaskInput) (Task, error)
	Get(ctx context.Context, id uuid.UUID) (Task, error)
	List(ctx context.Context, limit, offset int) ([]Task, int, error)
	Update(ctx context.Context, id uuid.UUID, input TaskInput) (Task, error)
	Delete(ctx context.Context, id uuid.UUID) error
}

type MemoryStore struct {
	mu    sync.RWMutex
	tasks map[uuid.UUID]Task
}

func NewMemoryStore() *MemoryStore {
	return &MemoryStore{tasks: make(map[uuid.UUID]Task)}
}

func (s *MemoryStore) Create(ctx context.Context, input TaskInput) (Task, error) {
	task := newTask(input.Title, false)
	if input.Done != nil {
		task.Done = *input.Done
	}
	if task.Title == "" {
		return Task{}, fmt.Errorf("%w: title is required", ErrInvalidInput)
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	s.tasks[task.ID] = task
	return task, nil
}

func (s *MemoryStore) Get(ctx context.Context, id uuid.UUID) (Task, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	task, ok := s.tasks[id]
	if !ok {
		return Task{}, ErrNotFound
	}
	return task, nil
}

type Page[T any] struct {
	Items  []T `json:"items"`
	Total  int `json:"total"`
	Limit  int `json:"limit"`
	Offset int `json:"offset"`
}

func (p Page[T]) Map[U any](transform func(T) U) Page[U] {
	items := make([]U, 0, len(p.Items))
	for _, item := range p.Items {
		items = append(items, transform(item))
	}
	return Page[U]{Items: items, Total: p.Total, Limit: p.Limit, Offset: p.Offset}
}

func (s *MemoryStore) List(ctx context.Context, limit, offset int) ([]Task, int, error) {
	if limit < 0 {
		limit = 0
	}
	if offset < 0 {
		offset = 0
	}

	s.mu.RLock()
	defer s.mu.RUnlock()

	tasks := make([]Task, 0, len(s.tasks))
	for _, task := range s.tasks {
		tasks = append(tasks, task)
	}
	slices.SortFunc(tasks, func(a, b Task) int {
		return -cmp.Compare(a.ID.String(), b.ID.String())
	})

	total := len(tasks)
	if offset >= total {
		return []Task{}, total, nil
	}
	end := min(offset+limit, total)
	return tasks[offset:end], total, nil
}

func (s *MemoryStore) Update(ctx context.Context, id uuid.UUID, input TaskInput) (Task, error) {
	title := strings.TrimSpace(input.Title)
	if title == "" {
		return Task{}, fmt.Errorf("%w: title is required", ErrInvalidInput)
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	task, ok := s.tasks[id]
	if !ok {
		return Task{}, ErrNotFound
	}
	task.Title = title
	if input.Done != nil {
		task.Done = *input.Done
	}
	task.UpdatedAt = time.Now()

	s.tasks[id] = task
	return task, nil
}

func (s *MemoryStore) Delete(ctx context.Context, id uuid.UUID) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	if _, ok := s.tasks[id]; !ok {
		return ErrNotFound
	}
	delete(s.tasks, id)
	return nil
}

type HTTPError struct {
	Status  int    `json:"status"`
	Message string `json:"message"`
}

func writeError(w http.ResponseWriter, status int, message string) {
	writeJSON(w, status, HTTPError{Status: status, Message: message})
}

func statusFor(err error) int {
	switch {
	case errors.Is(err, ErrNotFound):
		return http.StatusNotFound
	case errors.Is(err, ErrInvalidInput):
		return http.StatusUnprocessableEntity
	case errors.Is(err, ErrMalformedInput):
		return http.StatusBadRequest
	default:
		return http.StatusInternalServerError
	}
}

func errorMessage(err error) string {
	if statusFor(err) == http.StatusInternalServerError {
		return "internal server error"
	}
	return err.Error()
}

func createTask(store TaskStore) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		input, err := decodeInput(w, r)
		if err != nil {
			writeError(w, statusFor(err), errorMessage(err))
			return
		}

		task, err := store.Create(r.Context(), input)
		if err != nil {
			writeError(w, statusFor(err), errorMessage(err))
			return
		}

		w.Header().Set("Location", "/tasks/"+task.ID.String())
		writeJSON(w, http.StatusCreated, toDTO(task))
	}
}

func getTask(store TaskStore) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id, err := uuid.Parse(r.PathValue("id"))
		if err != nil {
			writeError(w, http.StatusBadRequest, "invalid task id")
			return
		}

		task, err := store.Get(r.Context(), id)
		if err != nil {
			writeError(w, statusFor(err), errorMessage(err))
			return
		}

		writeJSON(w, http.StatusOK, toDTO(task))
	}
}

func listTasks(store TaskStore) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		page := Page[Task]{
			Limit:  queryInt(r, "limit", 20),
			Offset: queryInt(r, "offset", 0),
		}
		items, total, err := store.List(r.Context(), page.Limit, page.Offset)
		if err != nil {
			writeError(w, statusFor(err), errorMessage(err))
			return
		}
		page.Items, page.Total = items, total

		writeJSON(w, http.StatusOK, page.Map(toDTO))
	}
}

func queryInt(r *http.Request, key string, fallback int) int {
	raw := r.URL.Query().Get(key)
	if raw == "" {
		return fallback
	}
	value, err := strconv.Atoi(raw)
	if err != nil || value < 0 {
		return fallback
	}
	return value
}

func updateTask(store TaskStore) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id, err := uuid.Parse(r.PathValue("id"))
		if err != nil {
			writeError(w, http.StatusBadRequest, "invalid task id")
			return
		}

		input, err := decodeInput(w, r)
		if err != nil {
			writeError(w, statusFor(err), errorMessage(err))
			return
		}

		task, err := store.Update(r.Context(), id, input)
		if err != nil {
			writeError(w, statusFor(err), errorMessage(err))
			return
		}

		writeJSON(w, http.StatusOK, toDTO(task))
	}
}

func deleteTask(store TaskStore) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id, err := uuid.Parse(r.PathValue("id"))
		if err != nil {
			writeError(w, http.StatusBadRequest, "invalid task id")
			return
		}

		if err := store.Delete(r.Context(), id); err != nil {
			writeError(w, statusFor(err), errorMessage(err))
			return
		}

		w.WriteHeader(http.StatusNoContent)
	}
}

type Middleware func(http.Handler) http.Handler

type requestIDKey struct{}

func withRequestID(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		id := r.Header.Get("X-Request-ID")
		if id == "" {
			id = uuid.NewV7().String()
		}

		ctx := context.WithValue(r.Context(), requestIDKey{}, id)
		w.Header().Set("X-Request-ID", id)
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

func withLogging(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		next.ServeHTTP(w, r)
		log.Printf("%s %s %s", r.Method, r.URL.Path, time.Since(start))
	})
}

func chain(handler http.Handler, middlewares ...Middleware) http.Handler {
	for i := len(middlewares) - 1; i >= 0; i-- {
		handler = middlewares[i](handler)
	}
	return handler
}

func withRecovery(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			if recovered := recover(); recovered != nil {
				log.Printf("panic: %v\n%s", recovered, debug.Stack())
				writeError(w, http.StatusInternalServerError, "internal server error")
			}
		}()

		next.ServeHTTP(w, r)
	})
}

func newServer(addr string) *http.Server {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /health", func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprintln(w, "ok")
	})

	return &http.Server{
		Addr:              addr,
		Handler:           mux,
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       10 * time.Second,
		WriteTimeout:      15 * time.Second,
		IdleTimeout:       60 * time.Second,
	}
}

func main() {
	server := newServer(":8080")

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	go func() {
		if err := server.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Fatalf("serve: %v", err)
		}
	}()

	<-ctx.Done()

	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := server.Shutdown(shutdownCtx); err != nil {
		log.Printf("shutdown: %v", err)
	}
}

func newRouter(store TaskStore) http.Handler {
	mux := http.NewServeMux()

	mux.HandleFunc("POST /tasks", createTask(store))
	mux.HandleFunc("GET /tasks", listTasks(store))
	mux.HandleFunc("GET /tasks/{id}", getTask(store))
	mux.HandleFunc("PUT /tasks/{id}", updateTask(store))
	mux.HandleFunc("DELETE /tasks/{id}", deleteTask(store))

	return chain(mux, withRequestID, withRecovery, withLogging)
}

func fetchTask(ctx context.Context, baseURL string, id uuid.UUID) (TaskDTO, error) {
	client := &http.Client{Timeout: 5 * time.Second}

	request, err := http.NewRequestWithContext(ctx, http.MethodGet, baseURL+"/tasks/"+id.String(), nil)
	if err != nil {
		return TaskDTO{}, err
	}

	response, err := client.Do(request)
	if err != nil {
		return TaskDTO{}, err
	}
	defer response.Body.Close()

	if response.StatusCode != http.StatusOK {
		return TaskDTO{}, fmt.Errorf("unexpected status: %s", response.Status)
	}
	return decodeTask(response)
}

func decodeTask(response *http.Response) (TaskDTO, error) {
	var task TaskDTO
	if err := json.NewDecoder(response.Body).Decode(&task); err != nil {
		return TaskDTO{}, err
	}
	return task, nil
}

func postTask(ctx context.Context, client *http.Client, baseURL, title string) (TaskDTO, error) {
	payload, err := json.Marshal(TaskInput{Title: title})
	if err != nil {
		return TaskDTO{}, err
	}

	request, err := http.NewRequestWithContext(ctx, http.MethodPost, baseURL+"/tasks", bytes.NewReader(payload))
	if err != nil {
		return TaskDTO{}, err
	}
	request.Header.Set("Content-Type", "application/json")

	response, err := client.Do(request)
	if err != nil {
		return TaskDTO{}, err
	}
	defer response.Body.Close()

	if response.StatusCode != http.StatusCreated {
		return TaskDTO{}, fmt.Errorf("unexpected status: %s", response.Status)
	}
	return decodeTask(response)
}

func responseError(response *http.Response) error {
	if response.StatusCode < http.StatusBadRequest {
		return nil
	}
	defer response.Body.Close()
	defer io.Copy(io.Discard, response.Body)

	var failure HTTPError
	if err := json.NewDecoder(response.Body).Decode(&failure); err != nil {
		return fmt.Errorf("unexpected status: %s", response.Status)
	}
	return fmt.Errorf("status %d: %s", failure.Status, failure.Message)
}

func newHTTPClient() *http.Client {
	transport := &http.Transport{
		MaxIdleConns:        100,
		MaxIdleConnsPerHost: 10,
		IdleConnTimeout:     90 * time.Second,
	}
	return &http.Client{
		Transport: transport,
		Timeout:   10 * time.Second,
	}
}

func getWithRetry(ctx context.Context, client *http.Client, url string) (*http.Response, error) {
	backoff := 100 * time.Millisecond
	var lastErr error

	for attempt := 0; attempt < 4; attempt++ {
		request, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
		if err != nil {
			return nil, err
		}

		response, err := client.Do(request)
		if err == nil && response.StatusCode < http.StatusInternalServerError {
			return response, nil
		}

		if err != nil {
			lastErr = err
		} else {
			lastErr = fmt.Errorf("server returned %s", response.Status)
			io.Copy(io.Discard, response.Body)
			response.Body.Close()
		}

		if attempt == 3 {
			break
		}

		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-time.After(backoff):
			backoff *= 2
		}
	}
	return nil, fmt.Errorf("giving up after 4 attempts: %w", lastErr)
}

func TestGetTask(t *testing.T) {
	store := NewMemoryStore()
	created, err := store.Create(context.Background(), TaskInput{Title: "write tests"})
	if err != nil {
		t.Fatal(err)
	}

	request := httptest.NewRequest(http.MethodGet, "/tasks/"+created.ID.String(), nil)
	request.SetPathValue("id", created.ID.String())
	recorder := httptest.NewRecorder()

	getTask(store).ServeHTTP(recorder, request)

	if recorder.Code != http.StatusOK {
		t.Fatalf("got status %d, want %d", recorder.Code, http.StatusOK)
	}

	var task TaskDTO
	if err := json.NewDecoder(recorder.Body).Decode(&task); err != nil {
		t.Fatal(err)
	}
	if task.ID != created.ID {
		t.Errorf("got id %s, want %s", task.ID, created.ID)
	}
}

