func TestTaskCRUD(t *testing.T) {
	store := NewMemoryStore()
	handler := newRouter(store)
	missing := uuid.NewV7().String()
	created, err := store.Create(context.Background(), TaskInput{Title: "existing"})
	if err != nil {
		t.Fatal(err)
	}

	tests := []struct {
		name       string
		method     string
		path       string
		body       string
		wantStatus int
	}{
		{"create", http.MethodPost, "/tasks", `{"title":"first"}`, http.StatusCreated},
		{"create malformed", http.MethodPost, "/tasks", `{"title":`, http.StatusBadRequest},
		{"create invalid", http.MethodPost, "/tasks", `{"title":""}`, http.StatusUnprocessableEntity},
		{"list", http.MethodGet, "/tasks", "", http.StatusOK},
		{"missing", http.MethodGet, "/tasks/" + missing, "", http.StatusNotFound},
		{"bad id", http.MethodGet, "/tasks/not-a-uuid", "", http.StatusBadRequest},
		{"update", http.MethodPut, "/tasks/" + created.ID.String(), `{"title":"updated"}`, http.StatusOK},
		{"delete", http.MethodDelete, "/tasks/" + created.ID.String(), "", http.StatusNoContent},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			var body io.Reader
			if test.body != "" {
				body = strings.NewReader(test.body)
			}

			request := httptest.NewRequest(test.method, test.path, body)
			recorder := httptest.NewRecorder()
			handler.ServeHTTP(recorder, request)

			if recorder.Code != test.wantStatus {
				t.Errorf("got status %d, want %d", recorder.Code, test.wantStatus)
			}
		})
	}
}

func openDB(path string) (*sql.DB, error) {
	db, err := sql.Open("sqlite", path)
	if err != nil {
		return nil, err
	}

	db.SetMaxOpenConns(1)
	db.SetMaxIdleConns(1)
	if !strings.Contains(path, "memory") {
		db.SetConnMaxLifetime(5 * time.Minute)
	}

	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
	defer cancel()

	if err := db.PingContext(ctx); err != nil {
		db.Close()
		return nil, err
	}
	return db, nil
}

func findTask(ctx context.Context, db *sql.DB, id uuid.UUID) (Task, error) {
	var (
		rawID     string
		task      Task
		done      int
		createdAt string
		updatedAt string
	)

	err := db.QueryRowContext(ctx,
		"SELECT id, title, done, created_at, updated_at FROM tasks WHERE id = ?",
		id.String(),
	).Scan(&rawID, &task.Title, &done, &createdAt, &updatedAt)
	if errors.Is(err, sql.ErrNoRows) {
		return Task{}, ErrNotFound
	}
	if err != nil {
		return Task{}, err
	}

	task.ID, err = uuid.Parse(rawID)
	if err != nil {
		return Task{}, err
	}
	task.Done = done != 0
	task.CreatedAt, err = time.Parse(time.RFC3339Nano, createdAt)
	if err != nil {
		return Task{}, err
	}
	task.UpdatedAt, err = time.Parse(time.RFC3339Nano, updatedAt)
	if err != nil {
		return Task{}, err
	}
	return task, nil
}

func fetchAllTasks(ctx context.Context, db *sql.DB) ([]Task, error) {
	rows, err := db.QueryContext(ctx,
		"SELECT id, title, done, created_at, updated_at FROM tasks ORDER BY id DESC")
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	tasks := make([]Task, 0)
	for rows.Next() {
		var (
			rawID     string
			task      Task
			done      int
			createdAt string
			updatedAt string
		)
		if err := rows.Scan(&rawID, &task.Title, &done, &createdAt, &updatedAt); err != nil {
			return nil, err
		}

		task.ID, err = uuid.Parse(rawID)
		if err != nil {
			return nil, err
		}
		task.Done = done != 0
		task.CreatedAt, err = time.Parse(time.RFC3339Nano, createdAt)
		if err != nil {
			return nil, err
		}
		task.UpdatedAt, err = time.Parse(time.RFC3339Nano, updatedAt)
		if err != nil {
			return nil, err
		}
		tasks = append(tasks, task)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return tasks, nil
}

func renameTask(ctx context.Context, db *sql.DB, id uuid.UUID, title string, done *bool) error {
	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback()

	result, err := tx.ExecContext(ctx,
		"UPDATE tasks SET title = ?, done = COALESCE(?, done), updated_at = ? WHERE id = ?",
		strings.TrimSpace(title),
		done,
		time.Now().Format(time.RFC3339Nano),
		id.String(),
	)
	if err != nil {
		return err
	}

	affected, err := result.RowsAffected()
	if err != nil {
		return err
	}
	if affected == 0 {
		return ErrNotFound
	}

	return tx.Commit()
}

type SQLStore struct {
	db *sql.DB
}

func NewSQLStore(db *sql.DB) *SQLStore {
	return &SQLStore{db: db}
}

func (s *SQLStore) Create(ctx context.Context, input TaskInput) (Task, error) {
	task := newTask(input.Title, false)
	if input.Done != nil {
		task.Done = *input.Done
	}
	if task.Title == "" {
		return Task{}, fmt.Errorf("%w: title is required", ErrInvalidInput)
	}
	if err := insertTask(ctx, s.db, task); err != nil {
		return Task{}, err
	}
	return task, nil
}

func (s *SQLStore) Get(ctx context.Context, id uuid.UUID) (Task, error) {
	return findTask(ctx, s.db, id)
}

func (s *SQLStore) List(ctx context.Context, limit, offset int) ([]Task, int, error) {
	if limit < 0 {
		limit = 0
	}
	if offset < 0 {
		offset = 0
	}

	tasks, err := fetchAllTasks(ctx, s.db)
	if err != nil {
		return nil, 0, err
	}
	total := len(tasks)
	if offset >= total {
		return []Task{}, total, nil
	}
	end := min(offset+limit, total)
	return tasks[offset:end], total, nil
}

func (s *SQLStore) Update(ctx context.Context, id uuid.UUID, input TaskInput) (Task, error) {
	title := strings.TrimSpace(input.Title)
	if title == "" {
		return Task{}, fmt.Errorf("%w: title is required", ErrInvalidInput)
	}
	if err := renameTask(ctx, s.db, id, title, input.Done); err != nil {
		return Task{}, err
	}
	return findTask(ctx, s.db, id)
}

func (s *SQLStore) Delete(ctx context.Context, id uuid.UUID) error {
	result, err := s.db.ExecContext(ctx, "DELETE FROM tasks WHERE id = ?", id.String())
	if err != nil {
		return err
	}
	affected, err := result.RowsAffected()
	if err != nil {
		return err
	}
	if affected == 0 {
		return ErrNotFound
	}
	return nil
}

var _ TaskStore = (*SQLStore)(nil)
